const setDomainCloudflareZone = `-- name: SetDomainCloudflareZone :exec
UPDATE domains
SET cf_zone_id = $1, cf_zone_name = $2,
    cf_proxied = $3,
    cf_status = CASE WHEN $1::text = '' THEN '' ELSE cf_status END,
    cf_message = '', cf_error = ''
WHERE id = $4
`

type SetDomainCloudflareZoneParams struct {
	ZoneID   string    `json:"zoneId"`
	ZoneName string    `json:"zoneName"`
	Proxied  bool      `json:"proxied"`
	ID       uuid.UUID `json:"id"`
}

// First zone match of a domain: its records are managed from now on, and it starts proxied unless the name cannot be.
func (q *Queries) SetDomainCloudflareZone(ctx context.Context, arg SetDomainCloudflareZoneParams) error {
	_, err := q.db.Exec(ctx, setDomainCloudflareZone,
		arg.ZoneID,
		arg.ZoneName,
		arg.Proxied,
		arg.ID,
	)
	return err
}

